const STAT_NAMES = {
  atk: '攻擊力',
  matk: '魔法攻擊力',
  str: '力量',
  dex: '敏捷',
  int: '智力',
  luk: '幸運',
  def: '物理防禦力',
  mdef: '魔法防禦力',
  hp: 'MaxHP',
  mp: 'MaxMP',
  speed: '移動速度',
  jump: '跳躍力',
  accuracy: '命中值',
  avoidability: '迴避值'
};

// 內嵌 MapleStory 官方正統音效 Base64
const ARTALE_SOUND_BASE64 = {
  "process": "",
  "use": "",
  "success": "",
  "fail": "",
  "destroy": "",
  "open": ""
};


// 音效系統 (包含 MapleStory 官方正統音效與 Web Audio API 0ms 即時解碼緩存)
class ArtaleSoundController {
  constructor() {
    this.audioCtx = null;
    this.audioBuffers = {};
    this.audioPool = {};
    this.castSource = null;
    this.castAudio = null;
    this.init();
  }

  init() {
    if (!this.audioCtx && typeof window !== 'undefined') {
      const AudioCtxClass = window.AudioContext || window.webkitAudioContext;
      if (AudioCtxClass) {
        this.audioCtx = new AudioCtxClass();
      }
    }
    this.decodeAllBuffers();

    // 瀏覽器音訊解鎖監聽（點擊任意處立即喚醒 Web Audio API）
    if (typeof window !== 'undefined') {
      const unlockAudio = () => {
        if (this.audioCtx && this.audioCtx.state === 'suspended') {
          this.audioCtx.resume();
        }
        window.removeEventListener('click', unlockAudio);
        window.removeEventListener('touchstart', unlockAudio);
      };
      window.addEventListener('click', unlockAudio);
      window.addEventListener('touchstart', unlockAudio);
    }
  }

  decodeAllBuffers() {
    if (typeof window === 'undefined') return;
    for (const [key, b64] of Object.entries(ARTALE_SOUND_BASE64)) {
      try {
        const bin = atob(b64);
        const len = bin.length;
        const bytes = new Uint8Array(len);
        for (let i = 0; i < len; i++) {
          bytes[i] = bin.charCodeAt(i);
        }

        // 1. 預創 Data URI HTML5 Audio (做為備用)
        if (typeof Audio !== 'undefined') {
          const snd = new Audio('data:audio/mp3;base64,' + b64);
          snd.preload = 'auto';
          this.audioPool[key] = snd;
        }

        // 2. 預先解碼至 Web Audio Buffer，達成 0.000 毫秒硬體零延遲即時發聲
        if (this.audioCtx) {
          this.audioCtx.decodeAudioData(bytes.buffer.slice(0), (decoded) => {
            this.audioBuffers[key] = decoded;
          }, () => {});
        }
      } catch (e) {}
    }
  }

  stopCastAudio() {
    if (this.castSource) {
      try {
        this.castSource.stop();
        this.castSource.disconnect();
      } catch (e) {}
      this.castSource = null;
    }
    if (this.castAudio) {
      try {
        this.castAudio.pause();
        this.castAudio.currentTime = 0;
      } catch (e) {}
      this.castAudio = null;
    }
  }

  playAudioFile(key, fallbackFn, isCast = false, loop = false) {
    if (isCast) {
      this.stopCastAudio();
    }

    // 優先使用 Web Audio API Buffer 播放 (0ms 零延遲，音畫毫秒級同步)
    if (this.audioCtx) {
      if (this.audioCtx.state === 'suspended') {
        this.audioCtx.resume().catch(() => {});
      }
      if (this.audioBuffers[key]) {
        try {
          const source = this.audioCtx.createBufferSource();
          source.buffer = this.audioBuffers[key];
          source.loop = loop;
          const gainNode = this.audioCtx.createGain();
          gainNode.gain.value = 0.85;
          source.connect(gainNode);
          gainNode.connect(this.audioCtx.destination);
          source.start(0);

          if (isCast) {
            this.castSource = source;
          }
          return;
        } catch (e) {}
      }
    }

    // 次選預緩存之 Data URI HTML5 Audio
    if (this.audioPool[key]) {
      try {
        const snd = this.audioPool[key].cloneNode();
        snd.volume = 0.85;
        snd.loop = loop;
        if (isCast) {
          this.castAudio = snd;
        }
        const playPromise = snd.play();
        if (playPromise && typeof playPromise.catch === 'function') {
          playPromise.catch(() => {
            if (typeof fallbackFn === 'function') fallbackFn.call(this);
          });
        }
        return;
      } catch (e) {}
    }

    if (typeof fallbackFn === 'function') fallbackFn.call(this);
  }

  playClick() {
    try {
      this.init();
      if (!this.audioCtx) return;
      const ctx = this.audioCtx;
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.type = 'sine';
      osc.frequency.setValueAtTime(800, ctx.currentTime);
      osc.frequency.exponentialRampToValueAtTime(400, ctx.currentTime + 0.05);
      gain.gain.setValueAtTime(0.15, ctx.currentTime);
      gain.gain.linearRampToValueAtTime(0.01, ctx.currentTime + 0.05);
      osc.connect(gain);
      gain.connect(ctx.destination);
      osc.start();
      osc.stop(ctx.currentTime + 0.05);
    } catch (e) {}
  }

  playScrollSuccessSynth() {
    try {
      this.init();
      if (!this.audioCtx) return;
      const ctx = this.audioCtx;
      const notes = [1046.50, 1318.51, 1567.98, 2093.00, 2637.02];
      notes.forEach((freq, idx) => {
        const osc = ctx.createOscillator();
        const gain = ctx.createGain();
        osc.type = 'triangle';
        osc.frequency.setValueAtTime(freq, ctx.currentTime + idx * 0.09);
        gain.gain.setValueAtTime(0.2, ctx.currentTime + idx * 0.09);
        gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + idx * 0.09 + 0.4);
        osc.connect(gain);
        gain.connect(ctx.destination);
        osc.start(ctx.currentTime + idx * 0.09);
        osc.stop(ctx.currentTime + idx * 0.09 + 0.4);
      });
    } catch (e) {}
  }

  playScrollFailSynth() {
    try {
      this.init();
      if (!this.audioCtx) return;
      const ctx = this.audioCtx;
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.type = 'sawtooth';
      osc.frequency.setValueAtTime(220, ctx.currentTime);
      osc.frequency.linearRampToValueAtTime(110, ctx.currentTime + 0.35);
      gain.gain.setValueAtTime(0.25, ctx.currentTime);
      gain.gain.linearRampToValueAtTime(0.01, ctx.currentTime + 0.35);
      osc.connect(gain);
      gain.connect(ctx.destination);
      osc.start();
      osc.stop(ctx.currentTime + 0.35);
    } catch (e) {}
  }

  playScrollExplodeSynth() {
    try {
      this.init();
      if (!this.audioCtx) return;
      const ctx = this.audioCtx;
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.type = 'sawtooth';
      osc.frequency.setValueAtTime(180, ctx.currentTime);
      osc.frequency.exponentialRampToValueAtTime(50, ctx.currentTime + 0.35);
      gain.gain.setValueAtTime(0.3, ctx.currentTime);
      gain.gain.linearRampToValueAtTime(0.01, ctx.currentTime + 0.35);
      osc.connect(gain);
      gain.connect(ctx.destination);
      osc.start();
      osc.stop(ctx.currentTime + 0.35);
    } catch (e) {}
  }

  // 播放楓之谷正統衝卷過程音效 (UI.img/Enchant - 1.57秒經典強化施法聲，與進度條完美同步)
  playProcess() {
    this.playAudioFile('process', this.playClick, true, false);
  }

  // 相容舊函式命名
  playHammer() {
    this.playProcess();
  }

  // 播放楓之谷衝卷成功官方音效 (Game.img/EnchantSuccess - 0.97秒金色楓葉清脆綻放音效)
  playSuccess() {
    this.stopCastAudio();
    this.playAudioFile('success', this.playScrollSuccessSynth, false, false);
  }

  // 播放楓之谷衝卷失敗官方音效 (Game.img/EnchantFailure - 1.12秒黑色裂痕楓葉碎裂音效)
  playFailure() {
    this.stopCastAudio();
    this.playAudioFile('fail', this.playScrollFailSynth, false, false);
  }

  // 播放楓之谷詛咒損毀官方音效 (UI.img/EnchantDestroy - 裝備碎裂特有音效)
  playBroken() {
    this.stopCastAudio();
    this.playAudioFile('destroy', this.playScrollExplodeSynth, false, false);
  }

  // 播放選擇/點擊卷軸展開音效 (UI.img/ScrollOpen - 經典羊皮卷軸攤開音效)
  playScrollOpen() {
    this.playAudioFile('open', this.playClick, false, false);
  }
}

const artaleSound = new ArtaleSoundController();

if (typeof window !== 'undefined') {
  window.ARTALE_EQUIPMENTS = ARTALE_EQUIPMENTS;
  window.ARTALE_SCROLLS = ARTALE_SCROLLS;
  window.STAT_NAMES = STAT_NAMES;
  window.artaleSound = artaleSound;
}

if (typeof module !== 'undefined' && module.exports) {
  module.exports = { ARTALE_EQUIPMENTS, ARTALE_SCROLLS, STAT_NAMES, artaleSound };
}
